from habits.cli import main
from habits.models import Habit
from habits.streaks import completion_rate, current_streak


class HabitsTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.file = str(Path(self.tmp.name) / 'habits.json')

    def cli(self, today, *args):
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            code = main(['--file', self.file, '--today', today, *args])
        return code, out.getvalue()

    def test_streaks(self):
        h = Habit('Read', 'daily', '2026-03-01', ['2026-03-02', '2026-03-03', '2026-03-04'])
        self.assertEqual(current_streak(h, date(2026, 3, 4)), 3)
        self.assertEqual(current_streak(h, date(2026, 3, 5)), 3)  # Today not done yet.
        self.assertEqual(current_streak(h, date(2026, 3, 6)), 0)
        w = Habit('Gym', 'weekdays', '2026-03-02', ['2026-03-05', '2026-03-06', '2026-03-09'])  # Thu, Fri, Mon
        self.assertEqual(current_streak(w, date(2026, 3, 9)), 3)
        self.assertEqual(completion_rate(h, date(2026, 3, 4)), 0.75)

    def test_cli(self):
        self.assertEqual(self.cli('2026-03-02', 'add', 'Read')[0], 0)
        self.assertEqual(self.cli('2026-03-02', 'add', 'read')[0], 1)
        self.cli('2026-03-02', 'done', 'Read')
        self.cli('2026-03-03', 'done', 'Read')
        self.assertEqual(self.cli('2026-03-03', 'list')[1], 'Read\tdaily\t2\n')
        self.assertEqual(self.cli('2026-03-04', 'today')[1], 'Read\n')
        self.assertEqual(self.cli('2026-03-03', 'stats', 'Read')[1], 'Streak: 2\nCompletion: 100%\n')
        self.assertEqual(self.cli('2026-03-03', 'export')[1], 'name,frequency,streak,completion\nRead,daily,2,1.0\n')
        self.assertEqual(self.cli('2026-03-03', 'add', 'X', '--frequency', 'hourly')[0], 1)


if __name__ == '__main__':
    unittest.main()
import argparse
import sys
from datetime import date

from . import export
from .models import Habit, HabitError
from .scheduler import due_today
from .storage import Storage
from .streaks import completion_rate, current_streak


def main(argv=None):
    parser = argparse.ArgumentParser(prog='habits')
    parser.add_argument('--file', default='habits.json')
    parser.add_argument('--today', type=date.fromisoformat, default=None, help='pretend today is this date (YYYY-MM-DD)')
    sub = parser.add_subparsers(dest='command', required=True)
    p = sub.add_parser('add')
    p.add_argument('name')
    p.add_argument('--frequency', default='daily')
    p = sub.add_parser('done')
    p.add_argument('name')
    sub.add_parser('list')
    sub.add_parser('today')
    p = sub.add_parser('stats')
    p.add_argument('name')
    sub.add_parser('export')
    args = parser.parse_args(argv)
    today = args.today or date.today()
    storage = Storage(args.file)
    try:
        habits = storage.load()
        if args.command == 'add':
            if any(h.name.lower() == args.name.lower() for h in habits):
                raise HabitError(f'{args.name!r} already exists')
            habits.append(Habit(args.name, args.frequency, today.isoformat()))
            storage.save(habits)
        elif args.command == 'done':
            habit = storage.find(habits, args.name)
            habit.done = sorted(set(habit.done) | {today.isoformat()})
            storage.save(habits)
        elif args.command == 'list':
            for habit in sorted(habits, key=lambda h: h.name.lower()):
                print(f'{habit.name}\t{habit.frequency}\t{current_streak(habit, today)}')
        elif args.command == 'today':
            for habit in due_today(habits, today):
                print(habit.name)
        elif args.command == 'stats':
            habit = storage.find(habits, args.name)
            print(f'Streak: {current_streak(habit, today)}')
            print(f'Completion: {round(completion_rate(habit, today) * 100)}%')
        elif args.command == 'export':
            print(export.habits_csv(habits, today), end='')
    except HabitError as error:
        print(f'habits: {error}', file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
